class Solution {
    public boolean circularArrayLoop(int[] nums) {
        int n = nums.length;
        for (int start = 0; start < n; start++) {
            if (nums[start] == 0) {
                continue;
            }

            int slow = start;
            int fast = start;
            while (sameDirection(nums, start, next(nums, slow))
                    && sameDirection(nums, start, next(nums, fast))
                    && sameDirection(nums, start, next(nums, next(nums, fast)))) {
                slow = next(nums, slow);
                fast = next(nums, next(nums, fast));
                if (slow == fast) {
                    if (slow == next(nums, slow)) {
                        break;
                    }
                    return true;
                }
            }

            int index = start;
            while (nums[index] != 0 && sameDirection(nums, start, index)) {
                int nextIndex = next(nums, index);
                nums[index] = 0;
                index = nextIndex;
            }
        }
        return false;
    }

    private boolean sameDirection(int[] nums, int start, int index) {
        return nums[index] != 0 && nums[index] * nums[start] > 0;
    }

    private int next(int[] nums, int index) {
        int n = nums.length;
        return ((index + nums[index]) % n + n) % n;
    }
}

class Solution {
    public boolean circularArrayLoop(int[] nums) {
        int n = nums.length;
        int[] color = new int[n];
        int colorId = 0;

        for (int start = 0; start < n; start++) {
            if (color[start] != 0) {
                continue;
            }
            colorId++;
            int index = start;
            while (color[index] == 0 && nums[index] * nums[start] > 0) {
                color[index] = colorId;
                index = next(nums, index);
            }

            if (color[index] == colorId) {
                int length = 1;
                int cursor = next(nums, index);
                while (cursor != index) {
                    length++;
                    cursor = next(nums, cursor);
                }
                if (length > 1) {
                    return true;
                }
            }
        }
        return false;
    }

    private int next(int[] nums, int index) {
        int n = nums.length;
        return ((index + nums[index]) % n + n) % n;
    }
}

class Solution {
    public boolean circularArrayLoop(int[] nums) {
        int n = nums.length;
        boolean[] processed = new boolean[n];

        for (int start = 0; start < n; start++) {
            if (processed[start]) {
                continue;
            }

            boolean forward = nums[start] > 0;
            java.util.Map<Integer, Integer> pathIndex = new java.util.HashMap<>();
            java.util.List<Integer> path = new java.util.ArrayList<>();
            int index = start;

            while (true) {
                if (processed[index] || (nums[index] > 0) != forward) {
                    break;
                }
                if (pathIndex.containsKey(index)) {
                    return true;
                }
                pathIndex.put(index, path.size());
                path.add(index);

                int nextIndex = next(nums, index);
                if (nextIndex == index) {
                    break;
                }
                index = nextIndex;
            }

            for (int visited : path) {
                processed[visited] = true;
            }
        }
        return false;
    }

    private int next(int[] nums, int index) {
        int n = nums.length;
        return ((index + nums[index]) % n + n) % n;
    }
}

class Solution {
    public boolean circularArrayLoop(int[] nums) {
        int n = nums.length;
        int[] seenAt = new int[n];
        int[] depth = new int[n];
        boolean[] done = new boolean[n];
        int stamp = 1;

        for (int start = 0; start < n; start++) {
            if (done[start]) {
                continue;
            }

            boolean forward = nums[start] > 0;
            int index = start;
            int step = 0;
            while (!done[index] && (nums[index] > 0) == forward) {
                int nextIndex = next(nums, index);
                if (nextIndex == index) {
                    break;
                }
                if (seenAt[index] == stamp) {
                    return step - depth[index] > 1;
                }
                seenAt[index] = stamp;
                depth[index] = step;
                step++;
                index = nextIndex;
            }

            index = start;
            while (!done[index] && seenAt[index] == stamp) {
                done[index] = true;
                index = next(nums, index);
            }
            stamp++;
        }
        return false;
    }

    private int next(int[] nums, int index) {
        int n = nums.length;
        return ((index + nums[index]) % n + n) % n;
    }
}
